import 'package:file_picker/file_picker.dart'; import 'package:flutter/material.dart'; import '../../core/app_state.dart'; import '../../core/models.dart';
class ImportScreen extends StatefulWidget{final AppState state;const ImportScreen({super.key,required this.state});@override State<ImportScreen> createState()=>_ImportScreenState();}
class _ImportScreenState extends State<ImportScreen>{bool busy=false;String message='';
 Future<void> pick()async{setState((){busy=true;message='Selecting files…';});try{final r=await FilePicker.platform.pickFiles(allowMultiple:true,withData:false);if(r==null){setState(()=>message='No files selected.');return;}var n=0;for(final f in r.files){if(f.path==null)continue;final e=f.name.toLowerCase().split('.').last;final k=['jpg','jpeg','png','webp'].contains(e)?'image':['pdf','docx','txt','md','html','csv'].contains(e)?'document':['epub'].contains(e)?'book':e=='zip'?'archive':'file';widget.state.addLibraryItem(LibraryItem(id:'${DateTime.now().microsecondsSinceEpoch}-$n',name:f.name,path:f.path!,kind:k,size:f.size));n++;}setState(()=>message='$n file(s) added to local library.');}catch(e){setState(()=>message='Import failed: $e');}finally{setState(()=>busy=false);}}
 @override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[Text('Import Center',style:Theme.of(c).textTheme.headlineMedium),const Text('Books • images • documents • notes • archives'),const SizedBox(height:18),FilledButton.icon(onPressed:busy?null:pick,icon:const Icon(Icons.folder_open),label:Text(busy?'Working…':'Choose files')),const Card(child:ListTile(leading:Icon(Icons.cloud_download),title:Text('Google Keep'),subtitle:Text('Primary migration path: Google Takeout/export. Live automatic sync is not enabled.'))),const Card(child:ListTile(leading:Icon(Icons.share),title:Text('Share from another app'),subtitle:Text('Planned. Requires platform share integration and permissions.'))),if(message.isNotEmpty)Text(message)]);
}
